+import { toUtcIsoString } from "./format.ts";
+import { allRecords, type RecordRow, type RecordStatus } from "./store.ts";
+
+export const DEFAULT_LIMIT = 20;
+export const MAX_LIMIT = 100;
+
+export interface ListQuery {
+  status?: RecordStatus;
+  nameContains?: string;
+  limit: number;
+  offset: number;
+}
+
+export interface ListItem {
+  id: string;
+  name: string;
+  status: RecordStatus;
+  createdAt: string;
+}
+
+export interface ListResult {
+  items: ListItem[];
+  total: number;
+  limit: number;
+  offset: number;
+}
+
+/** A caller-supplied list parameter is unusable. */
+export class QueryError extends Error {
+  readonly field: string;
+
+  constructor(field: string, message: string) {
+    super(message);
+    this.name = "QueryError";
+    this.field = field;
+  }
+}
+
+function parseCount(
+  raw: string | undefined,
+  field: string,
+  fallback: number,
+  min: number,
+  max: number,
+): number {
+  if (raw === undefined || raw === "") return fallback;
+  if (!/^\d+$/.test(raw)) {
+    throw new QueryError(field, `${field} must be a non-negative integer`);
+  }
+  const value = Number(raw);
+  if (value < min || value > max) {
+    throw new QueryError(field, `${field} must be between ${min} and ${max}`);
+  }
+  return value;
+}
+
+export function parseListQuery(query: Record<string, string | undefined>): ListQuery {
+  const rawStatus = query.status;
+  let status: RecordStatus | undefined;
+  if (rawStatus !== undefined && rawStatus !== "") {
+    if (rawStatus !== "active" && rawStatus !== "archived") {
+      throw new QueryError("status", "status must be active or archived");
+    }
+    status = rawStatus;
+  }
+
+  const rawName = query.nameContains;
+  const nameContains = rawName === undefined || rawName.trim() === "" ? undefined : rawName.trim();
+
+  return {
+    status,
+    nameContains,
+    limit: parseCount(query.limit, "limit", DEFAULT_LIMIT, 1, MAX_LIMIT),
+    offset: parseCount(query.offset, "offset", 0, 0, Number.MAX_SAFE_INTEGER),
+  };
+}
+
+function matches(record: RecordRow, query: ListQuery): boolean {
+  if (query.status !== undefined && record.status !== query.status) return false;
+  if (query.nameContains !== undefined) {
+    if (!record.name.toLowerCase().includes(query.nameContains.toLowerCase())) return false;
+  }
+  return true;
+}
+
+/**
+ * Lists the records matching the requested filters, one page at a time.
+ *
+ * Timestamps are returned through the shared UTC formatter: the store keeps
+ * offsets, the API never returns them.
+ */
+export function listRecords(query: ListQuery): ListResult {
+  const filtered = allRecords().filter((record) => matches(record, query));
+  const page = filtered.slice(query.offset, query.offset + query.limit);
+
+  return {
+    items: page.map((record) => ({
+      id: record.id,
+      name: record.name,
+      status: record.status,
+      createdAt: toUtcIsoString(record.createdAt),
+    })),
+    total: filtered.length,
+    limit: query.limit,
+    offset: query.offset,
+  };
+}
</file>
</review_files>

